import{_ as l,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-03-09 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-03-09 :: Ceph Orchestration Meeting","date":"2020-03-09T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","存储","分布式存储","Kubernetes","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-09_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-03-09_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2020/2020-03-09_-_-_Ceph_Orchestration_Meeting.md"};function o(n,e,s,h,u,_){return i(),t("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间与参与人员" tabindex="-1">会议时间与参与人员 <a class="header-anchor" href="#会议时间与参与人员" aria-label="Permalink to &quot;会议时间与参与人员&quot;">​</a></h4><ul><li>会议时间：周一，下午4点</li><li>参与人员：Pasi、Sebastian等</li></ul><h4 id="会议议题与讨论内容" tabindex="-1">会议议题与讨论内容 <a class="header-anchor" href="#会议议题与讨论内容" aria-label="Permalink to &quot;会议议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>会议时间调整</strong></p><ul><li>讨论了将会议时间从当前的4点推迟两小时的可能性，以适应俄罗斯作者的日程冲突。</li><li>Sebastian表示可以适应新的会议时间。</li></ul></li><li><p><strong>管理员密码问题</strong></p><ul><li>讨论了如何在命令中隐藏管理员密码，以避免在文档文件中暴露敏感信息。</li><li>提出两种解决方案：添加新参数或按参数隐藏信息。</li><li>决定首先明确解决方案，然后开始实施。</li></ul></li><li><p><strong>Python客户端集成</strong></p><ul><li>讨论了将Python客户端集成到rook组织中的进展。</li><li>确认相关文件已迁移到新的仓库，并计划后续跟进。</li></ul></li><li><p><strong>网络配置问题</strong></p><ul><li>讨论了在Kubernetes集群中网络配置的问题，特别是在使用不同网络提供商（如calico、flannel）时的兼容性问题。</li><li>确认了某些情况下，网络配置可能导致无法与服务通信的问题。</li></ul></li><li><p><strong>集群状态与配置</strong></p><ul><li>讨论了如何在Kubernetes中配置和管理Ceph集群的守护进程（demons）。</li><li>涉及到CRD（Custom Resource Definition）的使用和守护进程的自动管理。</li></ul></li><li><p><strong>数据安全与清理</strong></p><ul><li>讨论了在删除守护进程时如何处理数据，特别是监控器（monitors）的数据。</li><li>提出了备份数据和逐步删除的方案，以确保数据安全。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了Python客户端的集成进展，并计划后续跟进。</li><li>决定在删除守护进程时采取逐步删除和备份数据的策略，以确保数据安全。</li><li>确认了在Kubernetes中配置和管理Ceph集群守护进程的方案。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续跟进Python客户端的集成工作。</li><li>解决网络配置问题，特别是与服务通信的问题。</li><li>实施守护进程的自动管理和数据备份策略。</li><li>确保Ceph集群在Kubernetes中的稳定运行和管理。</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到的技术术语和产品名称（如Ceph、rook、Kubernetes、calico、flannel等）保持原文，以确保专业性和准确性。</li></ul>',11)])])}const d=l(r,[["render",o]]);export{c as __pageData,d as default};
